from bench.cdsfl_registry.composer import compose, DirectivePacket, PolicyViolationError

# Probe 1: a HARD situation packet must be preserved exactly and caller-owned input must not mutate.
hard = DirectivePacket(
    layer="situation",
    name="hard_situation_probe",
    text="Why: THIS HARD RATIONALE MUST REMAIN.\nMUST keep this HARD directive exactly.",
    constraint_class="HARD",
)
original = hard.text
result = compose("software", "deepseek_v3", situation=hard)
rendered_packet = next(p for p in result.packets if p.name == "hard_situation_probe")
if hard.text != original or rendered_packet.text != original:
    print("FALSIFIED: compose transformed or mutated a HARD situation packet")
else:
    # Probe 2: if HARD content alone exceeds the model cap, compose must fail loud;
    # returning raw character truncation silently removes HARD constraints.
    huge_hard = DirectivePacket(
        layer="situation",
        name="huge_hard_probe",
        text="MUST preserve this HARD directive exactly.\n" * 5000,
        constraint_class="HARD",
    )
    try:
        huge_result = compose("software", "deepseek_v3", situation=huge_hard)
    except PolicyViolationError:
        pass
    else:
        if huge_result.rendered_text.endswith("[... truncated for model capacity]"):
            print("FALSIFIED: compose globally truncated HARD directive text instead of failing loud")

